+          type="text"
+          autocomplete="name"
+          placeholder="Jordan Lee"
+          required
+          aria-describedby="full-name-error"
+        >
+        <p id="full-name-error" class="error-text" hidden></p>
+      </div>
+
+      <div class="form-field">
+        <label for="email">Email address <span class="required" aria-hidden="true">*</span></label>
+        <input
+          id="email"
+          name="email"
+          type="email"
+          autocomplete="email"
+          placeholder="jordan@example.com"
+          required
+          aria-describedby="email-error"
+        >
+        <p id="email-error" class="error-text" hidden></p>
+      </div>
+
+      <div class="form-field">
+        <label for="phone">Phone number</label>
+        <input
+          id="phone"
+          name="phone"
+          type="tel"
+          autocomplete="tel"
+          inputmode="tel"
+          placeholder="(555) 123-4567"
+          aria-describedby="phone-helper phone-error"
+        >
+        <p id="phone-helper" class="helper-text">Optional. Use digits only or a format like (555) 123-4567.</p>
+        <p id="phone-error" class="error-text" hidden></p>
+      </div>
+
+      <button type="submit">Submit</button>
+      <p id="form-status" class="status" hidden></p>
+    </form>
+  </main>
+
+  <script>
+    const form = document.getElementById('support-form');
+    const statusMessage = document.getElementById('form-status');
+    const fields = {
+      fullName: {
+        input: document.getElementById('full-name'),
+        error: document.getElementById('full-name-error'),
+        validate(value) {
+          if (!value.trim()) {
+            return 'Full name is required.';
+          }
+          return '';
+        }
+      },
+      email: {
+        input: document.getElementById('email'),
