+      statusMessage.textContent = '';
+      statusMessage.className = 'status';
+
+      const allValid = Object.values(fields).every((field) => validateField(field));
+
+      if (!allValid) {
+        const firstInvalid = Object.values(fields).find((field) => field.input.getAttribute('aria-invalid') === 'true');
+        if (firstInvalid) {
+          firstInvalid.input.focus();
+        }
+        return;
+      }
+
+      statusMessage.textContent = 'Your support request is ready to send.';
+      statusMessage.classList.add('success');
+      statusMessage.hidden = false;
+      form.reset();
+      Object.values(fields).forEach((field) => setFieldError(field, ''));
+    });
+  </script>
+</body>
+</html>
