      transform: translateY(-1px);
      filter: brightness(1.08);
    }

    @media (max-width: 600px) {
      .card {
        padding: 24px;
      }
    }
  </style>
</head>
<body>
  <main class="card">
    <h1>Contact Support</h1>
    <p class="intro">Need help with your account or a product issue? Send a message and our support team will get back to you.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
        <input
          id="full-name"
          name="fullName"
          type="text"
          autocomplete="name"
          placeholder="Jordan Lee"
          required
          aria-describedby="full-name-error"
        >
        <p id="full-name-error" class="error-text" hidden></p>
      </div>

      <div class="form-field">
        <label for="email">Email address <span class="required" aria-hidden="true">*</span></label>
        <input
          id="email"
          name="email"
          type="email"
          autocomplete="email"
          placeholder="jordan@example.com"
          required
          aria-describedby="email-error"
        >
        <p id="email-error" class="error-text" hidden></p>
      </div>

      <div class="form-field">
        <label for="phone">Phone number</label>
        <input
          id="phone"
          name="phone"
          type="tel"
          autocomplete="tel"
          inputmode="tel"
          placeholder="(555) 123-4567"
          aria-describedby="phone-helper phone-error"
        >
        <p id="phone-helper" class="helper-text">Optional. Use digits only or a format like (555) 123-4567.</p>
        <p id="phone-error" class="error-text" hidden></p>
      </div>

      <button type="submit">Submit</button>
      <p id="form-status" class="status" hidden></p>
    </form>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const statusMessage = document.getElementById('form-status');
    const fields = {
      fullName: {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        validate(value) {
          if (!value.trim()) {
            return 'Full name is required.';
          }
          return '';
        }
      },
      email: {
        input: document.getElementById('email'),
        error: document.getElementById('email-error'),
        validate(value) {
          if (!value.trim()) {
            return 'Email address is required.';
          }
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return 'Enter a valid email address.';
          }
          return '';
        }
      },
      phone: {
        input: document.getElementById('phone'),
        error: document.getElementById('phone-error'),
        validate(value) {
          if (!value.trim()) {
            return '';
          }
          const phonePattern = /^[+\d\s().-]{7,20}$/;
          if (!phonePattern.test(value.trim())) {
            return 'Enter a valid phone number using digits and common separators.';
          }
          return '';
        }
      }
    };

    function setFieldError(field, message) {
      field.error.textContent = message;
      field.error.hidden = !message;
      field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      setFieldError(field, message);
      return !message;
    }

    Object.values(fields).forEach((field) => {
      field.input.addEventListener('blur', () => {
        validateField(field);
      });

      field.input.addEventListener('input', () => {
        if (!field.error.hidden) {
          validateField(field);
        }
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      statusMessage.hidden = true;
      statusMessage.textContent = '';
      statusMessage.className = 'status';

      const allValid = Object.values(fields).every((field) => validateField(field));

      if (!allValid) {
        const firstInvalid = Object.values(fields).find((field) => field.input.getAttribute('aria-invalid') === 'true');
        if (firstInvalid) {
          firstInvalid.input.focus();
        }
        return;
      }

      statusMessage.textContent = 'Your support request is ready to send.';
      statusMessage.classList.add('success');
      statusMessage.hidden = false;
      form.reset();
      Object.values(fields).forEach((field) => setFieldError(field, ''));
    });
  </script>
