 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1120;
       --panel: rgba(15, 23, 42, 0.92);
       --panel-border: rgba(148, 163, 184, 0.18);
       --text: #e2e8f0;
       --muted: #94a3b8;
       --accent: #7c3aed;
       --accent-strong: #8b5cf6;
       --input-bg: rgba(15, 23, 42, 0.85);
       --input-border: rgba(148, 163, 184, 0.22);
       --input-focus: rgba(124, 58, 237, 0.55);
       --danger: #fda4af;
       --success-bg: rgba(34, 197, 94, 0.14);
       --success-border: rgba(74, 222, 128, 0.3);
       --shadow: 0 24px 80px rgba(2, 6, 23, 0.45);
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Arial, Helvetica, sans-serif;
       background:
         radial-gradient(circle at top, rgba(124, 58, 237, 0.28), transparent 30%),
         linear-gradient(180deg, #020617 0%, #0f172a 100%);
       color: var(--text);
       display: grid;
       place-items: center;
       padding: 24px;
     }

     .card {
       width: min(100%, 560px);
       background: var(--panel);
       border: 1px solid var(--panel-border);
       border-radius: 20px;
       box-shadow: var(--shadow);
       padding: 32px;
       backdrop-filter: blur(18px);
     }

     h1 {
       margin: 0 0 12px;
       font-size: clamp(1.75rem, 3vw, 2.25rem);
       line-height: 1.1;
     }

     .intro {
       margin: 0 0 28px;
       color: var(--muted);
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 20px;
     }

     .form-field {
       display: grid;
       gap: 8px;
     }

     label {
       font-size: 0.95rem;
       font-weight: 700;
     }

     .required {
       color: var(--accent-strong);
     }

     input {
       width: 100%;
       border: 1px solid var(--input-border);
       border-radius: 14px;
       background: var(--input-bg);
       color: var(--text);
       padding: 14px 16px;
       font-size: 1rem;
       outline: none;
       transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
     }

     input::placeholder {
       color: #64748b;
     }

     input:focus {
       border-color: var(--accent-strong);
       box-shadow: 0 0 0 4px var(--input-focus);
       transform: translateY(-1px);
     }

     .helper-text,
     .error-text,
     .status {
       font-size: 0.9rem;
       line-height: 1.5;
     }

     .helper-text {
       color: var(--muted);
     }

     .error-text {
       color: var(--danger);
       min-height: 1.35em;
     }

     .status {
       border: 1px solid transparent;
       border-radius: 14px;
       padding: 12px 14px;
     }

     .status[hidden],
     .error-text[hidden] {
       display: none;
     }

     .status.success {
       background: var(--success-bg);
       border-color: var(--success-border);
       color: #bbf7d0;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 14px 20px;
       font-size: 1rem;
       font-weight: 700;
       color: #f8fafc;
       background: linear-gradient(135deg, var(--accent) 0%, #2563eb 100%);
       cursor: pointer;
       transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
       box-shadow: 0 16px 36px rgba(37, 99, 235, 0.25);
     }

     button:hover,
     button:focus-visible {
       transform: translateY(-1px);
       filter: brightness(1.08);
     }

     @media (max-width: 600px) {
       .card {
         padding: 24px;
       }
     }
   </style>
